def flatten_json(obj):
    result = {}
    def _flatten(value, prefix):
        if isinstance(value, dict):
            for k in sorted(value.keys()):
                new_prefix = f"{prefix} > {k}" if prefix else k
                _flatten(value[k], new_prefix)
        elif isinstance(value, list):
            use_one = prefix.endswith("]")
            for i, elem in enumerate(value):
                idx = i+1 if use_one else i
                new_prefix = f"{prefix}[{idx}]"
                _flatten(elem, new_prefix)
        else:
            result[prefix] = value
    if isinstance(obj, dict):
        for k in sorted(obj.keys()):
            v = obj[k]
            prefix = k
            if isinstance(v, (dict, list)):
                _flatten(v, prefix)
            else:
                result[prefix] = v
    elif isinstance(obj, list):
        _flatten(obj, "")
    return result

def get_by_path(obj, path_str):
    if " > " in path_str or "[" in path_str:
        parts = path_str.split(" > ")
        cur = obj
        for pi, part in enumerate(parts):
            m = re.match(r'^([^\[]+)((?:\[\d+\])*)$', part)
            if not m:
                return None
            base = m.group(1)
            idx_part = m.group(2)
            if not isinstance(cur, dict):
                return None
            if base not in cur:
                return None
            cur = cur[base]
            if idx_part:
                indices = re.findall(r'\[(\d+)\]', idx_part)
                for j, idx_s in enumerate(indices):
                    displayed = int(idx_s)
                    if j == 0:
                        actual = displayed
                    else:
                        actual = displayed - 1
                    if not isinstance(cur, list):
                        return None
                    if actual <0 or actual >= len(cur):
                        return None
                    cur = cur[actual]
        return cur
    else:
        if isinstance(obj, dict) and path_str in obj:
            return obj[path_str]
        return None

def format_epoch_timestamp(value):
    try:
        if isinstance(value, bool):
            return None
        if isinstance(value, int):
            num = value
        elif isinstance(value, float):
            return None
        elif isinstance(value, str):
            s = value.strip()
            if re.fullmatch(r'-?\d+', s):
                num = int(s)
            else:
                return None
        else:
            return None
    except:
        return None
    now = time.time()
    try:
        diff_sec = abs(num - now)
        diff_ms = abs(num/1000.0 - now)
        if diff_sec <= diff_ms:
            try:
                dt = datetime.datetime.utcfromtimestamp(num)
                return dt.strftime("%Y-%m-%dT%H:%M:%S.000Z")
            except:
                try:
                    dt2 = datetime.datetime.utcfromtimestamp(num/1000.0)
                    millis = num % 1000
                    base = dt2.strftime("%Y-%m-%dT%H:%M:%S")
                    return f"{base}.{millis:03d}Z"
                except:
                    return None
        else:
            try:
                dt = datetime.datetime.utcfromtimestamp(num/1000.0)
                millis = num % 1000
                base = dt.strftime("%Y-%m-%dT%H:%M:%S")
                return f"{base}.{millis:03d}Z"
            except:
                return None
    except:
        return None

def detect_time_value(json_obj, time_keys):
    for key in time_keys:
        val = get_by_path(json_obj, key)
        if val is not None:
            if isinstance(val, (int, float)) and not isinstance(val, bool):
                if isinstance(val, float):
                    return str(val)
                conv = format_epoch_timestamp(val)
                if conv is not None:
                    return conv
                else:
                    return str(val)
            elif isinstance(val, str):
                conv = format_epoch_timestamp(val)
                if conv is not None:
                    return conv
                else:
                    return val
            else:
                return str(val) if val is not None else ""
    return ""

def detect_level_value(json_obj, level_keys, level_map):
    for key in level_keys:
        val = get_by_path(json_obj, key)
        if val is not None:
            if isinstance(val, bool):
                s = str(val).lower()
            elif isinstance(val, (int, float)):
                s = str(val)
            elif val is None:
                s = "null"
            else:
                s = str(val)
            if s in level_map:
                s = level_map[s]
            return s
    return "unknown"

def detect_message_value(json_obj, message_keys, substitute, context_key, placeholder_format):
    for key in message_keys:
        val = get_by_path(json_obj, key)
        if val is not None:
            if isinstance(val, (dict, list)):
                s = json.dumps(val)
            else:
                s = str(val) if val is not None else ""
            if substitute:
                ctx = get_by_path(json_obj, context_key)
                if ctx is None:
                    # try direct key?
                    ctx = json_obj.get(context_key)
                    if ctx is None:
                        ctx = {}
                if "key" not in placeholder_format:
                    return s
                parts = placeholder_format.split("key", 1)
                prefix = parts[0]
                suffix = parts[1] if len(parts)>1 else ""
                if isinstance(ctx, list):
                    mapping = {str(i): ctx[i] for i in range(len(ctx))}
                elif isinstance(ctx, dict):
                    mapping = {str(k): ctx[k] for k in ctx.keys()}
                else:
                    mapping = {}
                result = s
                for k in sorted(mapping.keys(), key=lambda x: -len(x)):
                    placeholder = prefix + k + suffix
                    if placeholder in result:
                        colored = format_value_for_subst(mapping[k])
                        result = result.replace(placeholder, colored)
                esc_prefix = re.escape(prefix)
                esc_suffix = re.escape(suffix)
                pattern = re.compile(esc_prefix + r'(.*?)' + esc_suffix)
                def repl_missing(m):
                    inner = m.group(1)
                    return f"\x1b[2m{prefix}\x1b[0m\x1b[1;31m{inner}\x1b[0m\x1b[2m{suffix}\x1b[0m"
                result = pattern.sub(repl_missing, result)
                return result
            else:
                return s
    return ""

def format_value_for_subst(value):
    if value is None:
        return f"\x1b[1mnull\x1b[0m"
    elif isinstance(value, bool):
        if value:
            return f"\x1b[1;32mtrue\x1b[0m"
        else:
            return f"\x1b[1;31mfalse\x1b[0m"
    elif isinstance(value, int) and not isinstance(value, bool):
        return f"\x1b[1;36m{value}\x1b[0m"
    elif isinstance(value, float):
        return f"\x1b[1;36m{value}\x1b[0m"
    elif isinstance(value, str):
        return f"\x1b[1;33m{value}\x1b[0m"
    elif isinstance(value, list):
        parts = [format_value_for_subst(elem) for elem in value]
        inner = f"\x1b[2m, \x1b[0m".join(parts)
        return f"\x1b[2m[\x1b[0m{inner}\x1b[2m]\x1b[0m"
    elif isinstance(value, dict):
        parts = []
        for k in sorted(value.keys()):
            v = value[k]
            key_colored = f"\x1b[35m{k}\x1b[0m"
            val_colored = format_value_for_subst(v)
            parts.append(f"{key_colored}\x1b[2m: \x1b[0m{val_colored}")
        inner = f"\x1b[2m, \x1b[0m".join(parts)
        return f"\x1b[2m{{\x1b[0m{inner}\x1b[2m}}\x1b[0m"
    else:
        return f"\x1b[1;33m{str(value)}\x1b[0m"

def format_value_for_dump(value, key):
    if value is None:
        return "null"
    elif isinstance(value, bool):
        return "true" if value else "false"
    elif isinstance(value, (int, float)):
        if isinstance(value, float):
            return str(value)
        else:
            return str(value)
    elif isinstance(value, str):
        if "[" in key:
            return json.dumps(value)
        else:
            return value
    else:
        return str(value)

def make_handlebars_renderer():
    helpers = {}
    def helper_fixed_size(args):
        try:
            size = int(args[0])
        except:
            size = 0
        val = str(args[1]) if len(args)>1 else ""
        if len(val) > size:
            return val[:size]
        else:
            return val.rjust(size)
    def helper_min_size(args):
        try:
            size = int(args[0])
        except:
            size = 0
        val = str(args[1]) if len(args)>1 else ""
        if len(val) >= size:
            return val
        else:
            return val.rjust(size)
    def helper_uppercase(args):
        val = str(args[0]) if args else ""
        return val.upper()
    def helper_bold(args):
        val = str(args[0]) if args else ""
        return f"\x1b[1m{val}\x1b[0m"
    def helper_cyan(args):
        val = str(args[0]) if args else ""
        return f"\x1b[36m{val}\x1b[0m"
    def helper_color_rgb(args):
        if len(args) <4:
            return ""
        try:
            r=int(args[0]); g=int(args[1]); b=int(args[2])
        except:
            r=g=b=0
        val=str(args[3])
        return f"\x1b[38;2;{r};{g};{b}m{val}\x1b[0m"
    def helper_level_style(args):
        val = str(args[0]) if args else ""
        low = val.lower()
        if low == "trace":
            col = "\x1b[1;36m"
        elif low == "debug":
            col = "\x1b[1;34m"
        elif low == "info":
            col = "\x1b[1;32m"
        elif low in ("warn","warning"):
            col = "\x1b[1;33m"
        elif low == "error":
            col = "\x1b[1;31m"
        elif low == "fatal":
            col = "\x1b[1;35m"
        elif low == "unknown":
            col = "\x1b[1;35m"
        else:
            col = "\x1b[1;35m"
        return f"{col}{val}\x1b[0m"
    helpers["fixed_size"] = helper_fixed_size
    helpers["min_size"] = helper_min_size
    helpers["uppercase"] = helper_uppercase
    helpers["bold"] = helper_bold
    helpers["cyan"] = helper_cyan
    helpers["color_rgb"] = helper_color_rgb
    helpers["level_style"] = helper_level_style

    def parse_full_expr(s, ctx):
        s=s.strip()
        if not s:
            return ""
        for h in sorted(helpers.keys(), key=lambda x: -len(x)):
            if s.startswith(h):
                after=len(h)
                if after < len(s) and s[after] not in (" ", "(", "\t", "\n"):
                    continue
                rest = s[after:].strip()
                args=[]
                pos=0
                n=len(rest)
                while pos<n:
                    while pos<n and rest[pos].isspace():
                        pos+=1
                    if pos>=n:
                        break
                    if rest[pos]=='(':
                        depth=1
                        i=pos+1
                        while i<n and depth>0:
                            if rest[i]=='(':
                                depth+=1
                            elif rest[i]==')':
                                depth-=1
                            elif rest[i] in ('"', "'"):
                                q=rest[i]
                                j=rest.find(q, i+1)
                                if j==-1:
                                    i=n
                                    break
                                i=j
                            i+=1
                        inner=rest[pos+1:i-1]
                        val = parse_full_expr(inner, ctx)
                        args.append(val)
                        pos=i
                    elif rest[pos] in ('"', "'"):
                        q=rest[pos]
                        j=rest.find(q, pos+1)
                        if j==-1:
                            val=rest[pos+1:]
                            args.append(val)
                            pos=n
                        else:
                            val=rest[pos+1:j]
                            args.append(val)
                            pos=j+1
                    else:
                        start=pos
                        while pos<n and not rest[pos].isspace() and rest[pos] not in ('(', ')'):
                            pos+=1
                        token=rest[start:pos]
                        if token.isdigit():
                            args.append(token)
                        else:
                            if token in ctx:
                                args.append(str(ctx[token]))
                            else:
                                args.append("")
                        while pos<n and rest[pos].isspace():
                            pos+=1
                        continue
                try:
                    return helpers[h](args)
                except:
                    return ""
        if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
            return s[1:-1]
        if s.startswith('(') and s.endswith(')'):
            inner=s[1:-1]
            return parse_full_expr(inner, ctx)
        if s in ctx:
            return str(ctx[s])
        else:
            if s.isdigit():
                return s
            return ""

    def render(template, ctx):
        import re
        # Handle #if blocks
        pattern_if = re.compile(r'\{\{#if\s+([^}]+)\}\}(.*?)\{\{\/if\}\}', re.DOTALL)
        def repl_if(m):
            var = m.group(1).strip()
            content = m.group(2)
            if "{{else}}" in content:
                true_part, false_part = content.split("{{else}}", 1)
            else:
                true_part, false_part = content, ""
            val = ctx.get(var, "")
            is_truthy=False
            if isinstance(val, bool):
                is_truthy=val
            elif isinstance(val, (int, float)):
                is_truthy=val!=0
            elif isinstance(val, str):
                is_truthy=val.strip()!="" and val!="0" and val.lower()!="false"
            elif val is not None:
                is_truthy=bool(val)
            if is_truthy:
                return true_part
            else:
                return false_part
        prev=None
        cur=template
