                            pos=j+1
                    else:
                        start=pos
                        while pos<n and not rest[pos].isspace() and rest[pos] not in ('(', ')'):
                            pos+=1
                        token=rest[start:pos]
                        if token.isdigit():
                            args.append(token)
                        else:
                            if token in ctx:
                                args.append(str(ctx[token]))
                            else:
                                args.append("")
                        while pos<n and rest[pos].isspace():
                            pos+=1
                        continue
                try:
                    return helpers[h](args)
                except:
                    return ""
        if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
            return s[1:-1]
        if s.startswith('(') and s.endswith(')'):
            inner=s[1:-1]
            return parse_full_expr(inner, ctx)
        if s in ctx:
            return str(ctx[s])
        else:
            if s.isdigit():
                return s
            return ""
    def render(template, ctx):
        import re
        pattern_if = re.compile(r'\{\{#if\s+([^}]+)\}\}(.*?)\{\{\/if\}\}', re.DOTALL)
        def repl_if(m):
            var = m.group(1).strip()
            content = m.group(2)
            if "{{else}}" in content:
                true_part, false_part = content.split("{{else}}", 1)
            else:
                true_part, false_part = content, ""
            val = ctx.get(var, "")
            is_truthy=False
            if isinstance(val, bool):
                is_truthy=val
            elif isinstance(val, (int, float)):
                is_truthy=val!=0
            elif isinstance(val, str):
                is_truthy=val.strip()!="" and val!="0" and val.lower()!="false"
            elif val is not None:
                is_truthy=bool(val)
            if is_truthy:
                return true_part
            else:
                return false_part
        prev=None
        cur=template
        while prev != cur:
            prev=cur
            cur=pattern_if.sub(repl_if, cur)
        tag_pat = re.compile(r'\{\{([^{}]+)\}\}')
        def repl_tag(m):
            expr=m.group(1).strip()
            if expr.startswith("#") or expr.startswith("/"):
                return ""
            return parse_full_expr(expr, ctx)
        result = tag_pat.sub(repl_tag, cur)
        return result
    return render

