def lua_repr(value):
    if value is None:
        return "nil"
    elif isinstance(value, bool):
        return "true" if value else "false"
    elif isinstance(value, int):
        return str(value)
    elif isinstance(value, float):
        return str(value)
    elif isinstance(value, str):
        # Escape backslash and double quote, preserve newline/tab as actual chars? We'll preserve
        esc = value.replace("\\", "\\\\").replace('"', '\\"')
        return f'"{esc}"'
    elif isinstance(value, dict):
        parts=[]
        for k in sorted(value.keys()):
            v=value[k]
            # sanitize inner key? Keep as is? For lua, keys are sanitized already.
            parts.append(f"{k} = {lua_repr(v)}")
        return "{ " + ", ".join(parts) + " }" if parts else "{}"
    elif isinstance(value, list):
        parts=[lua_repr(x) for x in value]
        return "{" + ",".join(parts) + "}"
    else:
        return '"unsupported"'

