class DotDict(dict):
    def __getattr__(self, item):
        try:
            v = self[item]
            if isinstance(v, dict):
                return DotDict(v)
            return v
        except KeyError:
            raise AttributeError(item)
    def __getitem__(self, key):
        return dict.__getitem__(self, key)

